mapper.insert:
INSERT INTO loan_issue (
    issue_id, application_id, user_id, issue_amount, issue_status, issue_time, disbursement_card_id
) VALUES (
             #{issueId}, #{applicationId}, #{userId}, #{issueAmount}, #{issueStatus}, #{issueTime}, #{disbursementCardId}
         )

mapper.select:
SELECT COALESCE(SUM(li.issue_amount), 0) AS totalAmount, COUNT(li.issue_id) AS totalCount, COALESCE(ROUND(SUM(li.issue_amount) / NULLIF(COUNT(li.issue_id), 0), 2), 0) AS avgAmount, COALESCE(SUM(CASE WHEN DATE(li.issue_time) = CURDATE() THEN li.issue_amount ELSE 0 END), 0) AS todayAmount FROM loan_issue li WHERE li.issue_status = 'SUCCESS'
AND li.issue_time >= #{startDate}
AND li.issue_time <= CONCAT(#{endDate}, ' 23:59:59')
